preset.customCSS:
@import url("https://fonts.googleapis.com/css2?family=Special+Elite&family=Nanum+Myeongjo:wght@400;700&display=swap");

/* 바깥 래퍼: 메시지 폭을 확보하고 가운데 정렬합니다. */
.risu-chat > div {
  padding: 1.2rem .75rem .6rem;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  width: 100%;
}
.risu-chat > div > div {
  width: 100%;
  margin: auto;
  display: flex;
  justify-content: center;
}

/* 글꼴과 크기: 본문 글자 크기는 --rtnoir-font-size로 바꿉니다. */
.rtnoir {
  --rtnoir-bg-fill: transparent;
  --rtnoir-blur: none;
  --rtnoir-bg-edge: none;
  --rtnoir-font-body: "Nanum Myeongjo", "Noto Serif KR", serif;
  --rtnoir-font-display: "Special Elite", "Courier New", ui-monospace, monospace;
  --rtnoir-font-size: 16px;
  --rtnoir-line-height: 1.85;
  --rtnoir-para-gap: .85em;
  --rtnoir-dialog-weight: 700;
  --rtnoir-stamp: "CONFIDENTIAL";
}

/* 본문: RisuAI 기본 색·글꼴 변수에 테마 값을 연결합니다. */
.rtnoir {
  --risu-font-family: var(--rtnoir-font-body);
  --FontColorStandard: var(--rtnoir-ink);
  --FontColorBold: var(--rtnoir-ink);
  --FontColorItalic: var(--rtnoir-muted);
  --FontColorItalicBold: var(--rtnoir-muted);
  --FontColorQuote1: var(--rtnoir-muted);
  --FontColorQuote2: var(--rtnoir-dialog);
  position: relative;
  isolation: isolate;
  width: 100%;
  min-width: 0;
  color: var(--rtnoir-ink);
  font-family: var(--rtnoir-font-body);
  font-size: var(--rtnoir-font-size);
  line-height: var(--rtnoir-line-height);
}
.rtnoir, .rtnoir *, .rtnoir *::before, .rtnoir *::after { box-sizing: border-box; }
/* 바깥 래퍼 보정(.risu-chat > div > div)이 테마 루트를 flex로 바꾸지 않게 루트 배치를 고정합니다. */
.rtnoir.rtnoir { display: block; }
.rtnoir__content {
  min-width: 0;
  color: var(--rtnoir-ink);
  word-break: keep-all;
  overflow-wrap: anywhere;
}
.rtnoir__content .chattext {
  --tw-prose-code: var(--rtnoir-ink);
  --tw-prose-pre-code: var(--rtnoir-ink);
  --tw-prose-pre-bg: var(--rtnoir-tint);
  max-width: none;
  color: var(--rtnoir-ink);
  font-size: var(--rtnoir-font-size) !important;
  line-height: var(--rtnoir-line-height) !important;
}
.rtnoir__content :is(p, li, td, th, blockquote) {
  font-size: var(--rtnoir-font-size);
  line-height: var(--rtnoir-line-height);
}
.rtnoir__content p { margin: 0 0 var(--rtnoir-para-gap); }
.rtnoir__content p:last-child { margin-bottom: 0; }
.rtnoir__content :is(h1, h2, h3, h4, h5, h6) {
  --risu-font-family: var(--rtnoir-font-display);
  margin: 1.3em 0 .55em;
  color: var(--rtnoir-ink);
  font-family: var(--rtnoir-font-display);
  line-height: 1.4;
  font-weight: 700;
}
.rtnoir__content h1 { font-size: calc(var(--rtnoir-font-size) * 1.6); }
.rtnoir__content h2 { font-size: calc(var(--rtnoir-font-size) * 1.35); }
.rtnoir__content h3 { font-size: calc(var(--rtnoir-font-size) * 1.15); }
.rtnoir__content :is(h4, h5, h6) { font-size: var(--rtnoir-font-size); }
.rtnoir__content strong { font-weight: 700; }
.rtnoir__content em { color: var(--rtnoir-muted); }
.rtnoir__content mark[risu-mark="quote1"],
.rtnoir__content mark[risu-mark="blockquote1"] { color: var(--rtnoir-muted); background: transparent; }
.rtnoir__content mark[risu-mark="quote2"],
.rtnoir__content mark[risu-mark="blockquote2"] {
  color: var(--rtnoir-dialog);
  font-weight: var(--rtnoir-dialog-weight);
  background: transparent;
}
.rtnoir__content blockquote {
  margin: 1em 0;
  padding: .3em 1em;
  border-left: 3px solid var(--rtnoir-line);
  color: var(--rtnoir-muted);
}
.rtnoir__content :is(ul, ol) { margin: 1em 0; padding-left: 1.5em; }
.rtnoir__content li { margin: .25em 0; color: var(--rtnoir-ink); }
.rtnoir__content li::marker { color: var(--rtnoir-muted); }
.rtnoir__content a { color: var(--rtnoir-accent); text-decoration: underline; }
.rtnoir__content hr { border: 0; border-top: 1px solid var(--rtnoir-line); margin: 1.5em 0; }
.rtnoir__content code {
  --risu-font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  padding: .1em .3em;
  border-radius: .2em;
  color: var(--rtnoir-ink);
  background: var(--rtnoir-tint);
  font-family: "IBM Plex Mono", ui-monospace, Consolas, monospace;
  font-size: calc(var(--rtnoir-font-size) * .88);
}
.rtnoir__content pre {
  max-width: 100%;
  overflow-x: auto;
  padding: .9em 1em;
  color: var(--rtnoir-ink);
  background: var(--rtnoir-tint);
  border-radius: .35rem;
  font-size: calc(var(--rtnoir-font-size) * .88);
  line-height: 1.5;
}
.rtnoir__content pre code { padding: 0; background: transparent; color: inherit; white-space: pre; overflow-wrap: normal; }
.rtnoir__content table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
  margin: 1em 0;
}
.rtnoir__content :is(th, td) {
  padding: .5em .7em;
  color: var(--rtnoir-ink);
  border-bottom: 1px solid var(--rtnoir-line);
  text-align: left;
  vertical-align: top;
}
.rtnoir__content th { font-weight: 700; }
.rtnoir__content img { display: block; max-width: 100%; height: auto; margin: .75em auto; }
.rtnoir__content textarea.message-edit-area {
  width: 100%;
  max-width: 100%;
  min-width: 0;
  color: var(--rtnoir-ink) !important;
  background: var(--rtnoir-edit-bg) !important;
  border: 1px solid var(--rtnoir-line);
  border-radius: .4rem;
  font: inherit;
  font-size: var(--rtnoir-font-size) !important;
  line-height: var(--rtnoir-line-height) !important;
}

/* 조작부: 생성 정보와 버튼 */
.rtnoir__footer {
  --risu-theme-textcolor2: var(--rtnoir-muted);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: .4rem .75rem;
  min-width: 0;
}
.rtnoir__info, .rtnoir__actions { min-width: 0; max-width: 100%; }
.rtnoir__info > div, .rtnoir__actions > div { flex-wrap: wrap; min-width: 0; gap: .3rem; }
.rtnoir__actions > div > div { flex-wrap: wrap; min-width: 0; }
.rtnoir__footer button {
  background: transparent;
  min-height: 1.9rem;
  padding: .25rem .4rem;
  border-radius: .3rem;
  white-space: normal;
}
.rtnoir__footer button:hover { background: var(--rtnoir-tint); }
.rtnoir :is(a, button, textarea):focus-visible { outline: 2px solid var(--rtnoir-accent); outline-offset: 2px; }

/* 아바타 틀: RisuAI가 넣는 배경 이미지 칸을 틀에 맞춥니다. */
.rtnoir__portrait { overflow: hidden; background: var(--rtnoir-tint); }
.rtnoir__portrait > * {
  width: 100% !important;
  height: 100% !important;
  min-width: 0 !important;
  min-height: 0 !important;
  background-size: cover !important;
  background-position: center 22% !important;
  border: 0 !important;
  border-radius: inherit !important;
}

.rtnoir__bg {
  position: absolute;
  inset: 0;
  z-index: -1;
  pointer-events: none;
  border-radius: inherit;
  background: var(--rtnoir-bg-fill);
  -webkit-backdrop-filter: var(--rtnoir-blur);
  backdrop-filter: var(--rtnoir-blur);
  box-shadow: var(--rtnoir-bg-edge);
}

/* 구조: 현대 느와르 */

.rtnoir { max-width: 52rem; margin: 0 auto; padding-top: 1.7rem; }
/* 사다리꼴 파일 탭 */
.rtnoir__tab {
  position: absolute;
  top: 0;
  left: clamp(.8rem, 3%, 1.6rem);
  max-width: calc(100% - 9rem);
  padding: .32rem 1.6rem .26rem;
  background: var(--rtnoir-folder);
  clip-path: polygon(7% 0, 93% 0, 100% 100%, 0 100%);
  color: var(--rtnoir-folder-ink);
  font-family: var(--rtnoir-font-display);
  font-size: .78em;
  letter-spacing: .12em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.rtnoir__sheet {
  position: relative;
  padding: 1.4rem clamp(1rem, 4vw, 2rem) 1rem;
  background: var(--rtnoir-paper);
  border-top: 6px solid var(--rtnoir-folder);
  box-shadow: 0 6px 18px var(--rtnoir-shadow);
}
/* 도장: 파일 탭 오른쪽, 크기는 화면 폭에 맞춥니다 */
.rtnoir::after {
  content: var(--rtnoir-stamp);
  position: absolute;
  top: .1rem;
  right: clamp(.8rem, 3%, 1.4rem);
  padding: 0 .45rem;
  border: 2px solid var(--rtnoir-accent);
  border-radius: .2rem;
  color: var(--rtnoir-accent);
  font-family: var(--rtnoir-font-display);
  font-size: clamp(.55rem, 1.3vw, .78rem);
  letter-spacing: .2em;
  opacity: .6;
  transform: rotate(-4deg);
  pointer-events: none;
}
/* 클립으로 고정한 증명사진 */
.rtnoir__photo {
  position: relative;
  float: right;
  width: calc(var(--rtnoir-portrait-w) + .8rem);
  margin: .3rem 0 .8rem 1.2rem;
  padding: .4rem .4rem .3rem;
  background: var(--rtnoir-photo);
  box-shadow: 0 2px 6px var(--rtnoir-shadow);
  transform: rotate(2deg);
}
.rtnoir__photo::before {
  content: "";
  position: absolute;
  top: -.6rem;
  left: 22%;
  width: clamp(.7rem, 22%, 1.1rem);
  height: clamp(1.6rem, 50%, 2.4rem);
  border: 2px solid var(--rtnoir-clip);
  border-radius: 999px;
  transform: rotate(-6deg);
  pointer-events: none;
}
.rtnoir__portrait { width: 100%; aspect-ratio: 3 / 4; filter: var(--rtnoir-photo-filter); }
.rtnoir__caption { margin-top: .25rem; color: var(--rtnoir-photo-ink); font-family: var(--rtnoir-font-display); font-size: .7em; text-align: center; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rtnoir__content::after { content: ""; display: block; clear: both; }
.rtnoir__footer { clear: both; margin-top: .9rem; padding-top: .5rem; border-top: 1px solid var(--rtnoir-line); font-size: .82em; }
.rtnoir { --rtnoir-portrait-w: clamp(3.4rem, 11%, 5.6rem); }
.rtnoir--user { --rtnoir-portrait-w: clamp(2.6rem, 7%, 3.6rem); }
@media (max-width: 520px) { .rtnoir::after { display: none; } .rtnoir__tab { max-width: calc(100% - 1.6rem); } }

/* ── 배색과 소재: 이 블록만 바꾸면 같은 분류의 다른 변주가 됩니다. (신문지) ── */
.rtnoir {
  --rtnoir-paper: #e6d9be;
  --rtnoir-folder: #8a7350;
  --rtnoir-folder-ink: #f1e7d0;
  --rtnoir-photo: #f3ecda;
  --rtnoir-photo-ink: #3a2e20;
  --rtnoir-photo-filter: sepia(.8) contrast(1.05);
  --rtnoir-clip: #7d7466;
  --rtnoir-ink: #2b2218;
  --rtnoir-muted: #6b5a43;
  --rtnoir-accent: #76321f;
  --rtnoir-dialog: #2b2218;
  --rtnoir-shadow: rgba(60, 40, 15, .3);
  --rtnoir-line: #cbb995;
  --rtnoir-tint: #dacaa8;
  --rtnoir-edit-bg: #efe5cf;
  --rtnoir-stamp: "EXTRA";
}
